if (obj is Note other)
{
    return LastName == other.LastName &&
           Name == other.Name &&
           Patronymic == other.Patronymic &&
           Street == other.Street &&
           House == other.House &&
           Flat == other.Flat &&
           Phone == other.Phone;
}
return false;

var formatter = new BinaryFormatter();
using (FileStream fs = new FileStream(fileName, FileMode.OpenOrCreate))
{
    return (List<Note>)formatter.Deserialize(fs);
}

var newNotes = OpenFile(fileName);
foreach (var note in newNotes)
{
    if (!existing.Contains(note))
        existing.Add(note);
}
return existing;

var newNotes = OpenFile(fileName);
foreach (var note in newNotes)
{
    if (!existing.Contains(note))
        existing.Add(note);
}
return existing;

var notes = new List<Note>();
using (StreamReader sr = new StreamReader(fileName))
{
    while (!sr.EndOfStream)
    {
        var rec = new Note();
        rec.LastName = sr.ReadLine();
        rec.Name = sr.ReadLine();
        rec.Patronymic = sr.ReadLine();
        rec.Street = sr.ReadLine();
        rec.House = Convert.ToUInt16(sr.ReadLine());
        rec.Flat = Convert.ToUInt16(sr.ReadLine());
        rec.Phone = sr.ReadLine();
        notes.Add(rec);
    }
}
return notes;

var newNotes = OpenFile(fileName);
foreach (var note in newNotes)
{
    if (!existing.Contains(note))
        existing.Add(note);
}
return existing;

List<Note> notes = new List<Note>();
try
{
    XmlDocument xDoc = new XmlDocument();
    xDoc.Load(fileName);
    XmlElement xRoot = xDoc.DocumentElement;
    foreach (XmlElement xnode in xRoot)
    {
        Note node = new Note();
        foreach (XmlNode cnode in xnode.ChildNodes)
        {
            if (cnode.Name == "Lastname") node.LastName = cnode.InnerText;
            if (cnode.Name == "Name") node.Name = cnode.InnerText;
            if (cnode.Name == "Patronymic") node.Patronymic = cnode.InnerText;
            if (cnode.Name == "Street") node.Street = cnode.InnerText;
            if (cnode.Name == "House") node.House = Convert.ToUInt16(cnode.InnerText);
            if (cnode.Name == "Flat") node.Flat = Convert.ToUInt16(cnode.InnerText);
            if (cnode.Name == "Phone") node.Phone = cnode.InnerText;
        }
        notes.Add(node);
    }
}
catch (Exception)
{
    System.Windows.Forms.MessageBox.Show("xml файла не существует");
}
return notes;

var newNotes = OpenFile(fileName);
foreach (var note in newNotes)
{
    if (!existing.Contains(note))
        existing.Add(note);
}
return existing;

using (StreamWriter sw = new StreamWriter(fileName))
{
    foreach (Note MyRecord in notes)
    {
        sw.WriteLine(MyRecord.LastName);
        sw.WriteLine(MyRecord.Name);
        sw.WriteLine(MyRecord.Patronymic);
        sw.WriteLine(MyRecord.Street);
        sw.WriteLine(MyRecord.House);
        sw.WriteLine(MyRecord.Flat);
        sw.WriteLine(MyRecord.Phone);
    }
}

XmlTextWriter textWriter = new XmlTextWriter(fileName, Encoding.UTF8);
textWriter.WriteStartDocument();
textWriter.WriteStartElement("Notes");
textWriter.WriteEndElement();
textWriter.Close();

XmlDocument document = new XmlDocument();
document.Load(fileName);

int i = 0;
foreach (Note x in notes)
{
    XmlElement element = document.CreateElement("Note");
    document.DocumentElement.AppendChild(element);
    XmlAttribute attribute = document.CreateAttribute("id");
    attribute.Value = i.ToString();
    element.Attributes.Append(attribute);

    XmlNode lastnameElem = document.CreateElement("Lastname");
    lastnameElem.InnerText = x.LastName;
    element.AppendChild(lastnameElem);

    XmlNode nameElem = document.CreateElement("Name");
    nameElem.InnerText = x.Name;
    element.AppendChild(nameElem);

    XmlNode patronymicElem = document.CreateElement("Patronymic");
    patronymicElem.InnerText = x.Patronymic;
    element.AppendChild(patronymicElem);

    XmlNode streetElem = document.CreateElement("Street");
    streetElem.InnerText = x.Street;
    element.AppendChild(streetElem);

    XmlNode houseElem = document.CreateElement("House");
    houseElem.InnerText = x.House.ToString();
    element.AppendChild(houseElem);

    XmlNode flatElem = document.CreateElement("Flat");
    flatElem.InnerText = x.Flat.ToString();
    element.AppendChild(flatElem);

    XmlNode phoneElem = document.CreateElement("Phone");
    phoneElem.InnerText = x.Phone;
    element.AppendChild(phoneElem);

    i++;
}
document.Save(fileName);

var formatter = new BinaryFormatter();
var stream = new FileStream(fileName, FileMode.Create, FileAccess.Write, FileShare.None);
formatter.Serialize(stream, notes);
stream.Close();

var options = new JsonSerializerOptions
{
    WriteIndented = true
};
string json = JsonSerializer.Serialize(notes, options);
File.WriteAllText(fileName, json);

